'use strict';
let papers = [], filter = 'all';
const list = document.querySelector('#paper-list'), search = document.querySelector('#paper-search'), dialog = document.querySelector('#figure-dialog');
const escapeHTML = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function openFigure(p){document.querySelector('#figure-title').textContent=p.title;const img=document.querySelector('#figure-image');img.src=p.image;img.alt=p.imageAlt||`Figure from ${p.title}`;document.querySelector('#figure-caption').textContent=p.caption||'Figure from the linked paper.';document.querySelector('#figure-source').href=p.url;dialog.showModal();}
function render(){const q=search.value.toLowerCase().trim();const shown=papers.filter(p=>(filter==='all'||p.category===filter)&&[p.title,p.authors,p.venue,p.year].join(' ').toLowerCase().includes(q));document.querySelector('#result-count').textContent=`${shown.length} ${shown.length===1?'paper':'papers'}`;list.innerHTML=shown.length?shown.map(p=>`<article class="paper" id="paper-${p.id}"><div>${p.image?`<button class="figure-button" data-figure="${p.id}" aria-label="Enlarge figure: ${escapeHTML(p.title)}"><img src="${escapeHTML(p.image)}" alt="${escapeHTML(p.imageAlt||'Figure from '+p.title)}" loading="lazy" width="340" height="230"><span class="zoom" aria-hidden="true">⤢</span></button>`:`<a class="figure-placeholder" href="${escapeHTML(p.url)}" aria-label="Read ${escapeHTML(p.title)}">${escapeHTML(p.venue==='Preprint'?p.year:p.venue.split(' ').slice(0,2).join(' '))}</a>`}</div><div><div class="paper-venue">${escapeHTML(p.venue)}${p.venue==='Preprint'?' · '+p.year:''}</div><h3><a href="${escapeHTML(p.url)}">${escapeHTML(p.title)}</a></h3><p class="authors">${escapeHTML(p.authors).replace(/Weimin Wu\s*\*?/g,m=>`<strong>${m}</strong>`)}</p><div class="paper-links"><a href="${escapeHTML(p.url)}">Paper ↗</a>${p.code?`<a href="${escapeHTML(p.code)}">Code ↗</a>`:''}${p.image?`<button data-figure="${p.id}">${p.assetType==='algorithm-excerpt'?'Algorithm':'Figure'} ⤢</button>`:''}</div></div></article>`).join(''):'<p class="empty-state">No papers match your search. Try another title, author, year, or venue.</p>';}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b?'true':'false');});render();}));
search.addEventListener('input',render);list.addEventListener('click',e=>{const b=e.target.closest('[data-figure]');if(b)openFigure(papers.find(p=>p.id===Number(b.dataset.figure)));});
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
fetch('papers.json').then(r=>{if(!r.ok)throw Error('Unable to load papers');return r.json();}).then(data=>{papers=data;render();}).catch(()=>{list.innerHTML='<p>Visit <a href="https://weiminwu.academicwebsite.com/publications">my publication archive</a> to explore all papers.</p>';document.querySelector('#result-count').textContent='Publication archive';});
